// Site tracker plan: one job per tracked site. Sites come from the Data Table "seo_sites" (registered through the form option
// "Track my site" / API mode "track") plus every domain that has a keyword ladder (registered automatically, e-mail from the ladder).
// Google data is read for the last 28 complete days ending 3 days ago (Search Console data is final after about 3 days),
// against the 28 days before and the same 28 days a year earlier.
const CONFIG = {
  service_account_email: 'devai-seo@techand-site.iam.gserviceaccount.com',   // filled from n8n/.env (SEO_GOOGLE_SA_EMAIL) at build time; shown in the connect instructions
  max_sites_per_run: 25, max_tracked_keywords: 40, max_gsc_keyword_requests: 30, max_inspections: 20, max_trend_keywords: 4, max_serp_checks: 20,
  striking_min_impressions: 30,     // "striking distance": position 4-20 with at least this many impressions in 28 days
  ctr_gap_min_impressions: 100,     // CTR gap: top-10 position, at least this many impressions, CTR under half the expected rate for the position
  decay_drop_pct: 25,               // decaying page: clicks down by this much vs the previous 28 days (and at least 10 clicks before)
  alert_drop_pct: 30                // alert when site clicks / organic sessions drop by this much
};
let trigger = {}; try { const t = $('Manual Run').first(); trigger = (t && t.json) || {}; } catch (e) {}
if (trigger.body && typeof trigger.body === 'object') trigger = { ...trigger, ...trigger.body };
const rowsOf = (name) => { try { return $(name).all().map(i => i.json).filter(r => r && typeof r === 'object' && !r.error); } catch (e) { return []; } };
const normD = (x) => String(x || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const siteIdFor = (d) => 'site_' + d.replace(/[^a-z0-9]+/g, '-');
const kwList = (s) => String(s || '').split(/[\n,;]+/).map(k => k.trim().toLowerCase().replace(/\s+/g, ' ')).filter(Boolean);
const sites = rowsOf('Load Sites').filter(r => r.site_id && r.domain);
const ladders = rowsOf('Load Ladders').filter(r => r.ladder_id && r.domain && r.keyword);
const history = rowsOf('Load Rank History').filter(r => r.keyword && r.checked_at);
const logRows = rowsOf('Load Content Log').filter(r => r.keyword && r.domain);   // pages written by the Content Cadence / reported as published
const alertRows = rowsOf('Load Console Alerts').filter(r => r.domain && r.kind);     // Search Console notification mails + check-in flags
const checkinRows = rowsOf('Load Check-ins').filter(r => r.site_id && r.month);     // monthly owner check-ins (manual action / security / Pages export)
const byDomain = new Map();
for (const s of sites) { const d = normD(s.domain); if (d && !byDomain.has(d)) byDomain.set(d, { ...s, domain: d, keywords: kwList(s.keywords), virtual: false }); }
for (const l of ladders) { const d = normD(l.domain); if (d && !byDomain.has(d)) byDomain.set(d, { site_id: siteIdFor(d), domain: d, gsc_property: '', ga4_property_id: '', country: l.country || '', location_code: Number(l.location_code) || 0, language_code: l.language_code || 'en', email: l.email || '', callback_url: l.callback_url || '', keywords: [], status: 'active', source: 'ladder', created_at: '', last_run_at: '', request_id: l.request_id || '', virtual: true }); }
// a registered site without an address inherits the ladder's e-mail / callback for the same domain (API registrations with callback only)
for (const s of byDomain.values()) { if (s.email && s.callback_url) continue; const l = ladders.find(l => normD(l.domain) === s.domain && (l.email || l.callback_url)); if (l) { s.email = s.email || l.email || ''; s.callback_url = s.callback_url || l.callback_url || ''; } }
const want = normD(trigger.domain) || String(trigger.site_id || '').trim();
const on_demand = !!want;
let list = [...byDomain.values()];
if (on_demand) list = list.filter(s => s.domain === want || s.site_id === want);
else list = list.filter(s => String(s.status || 'active') !== 'paused');
if (!list.length) return [{ json: { nothing_to_do: true, reason: on_demand ? 'no tracked site matches "' + want + '"' : 'no sites to track yet (register one through "Track my site" or plan a keyword ladder)', sites: byDomain.size } }];
const end = new Date(Date.now() - 3 * 864e5); end.setUTCHours(0, 0, 0, 0);
const iso = (d) => d.toISOString().slice(0, 10); const addDays = (d, n) => new Date(d.getTime() + n * 864e5);
const ranges = { current: { start: iso(addDays(end, -27)), end: iso(end) }, previous: { start: iso(addDays(end, -55)), end: iso(addDays(end, -28)) }, yoy: { start: iso(addDays(end, -27 - 364)), end: iso(addDays(end, -364)) } };
const now = new Date().toISOString();
return list.slice(0, CONFIG.max_sites_per_run).map(s => {
  const lrows = ladders.filter(l => normD(l.domain) === s.domain).sort((a, b) => (Number(a.rung) || 0) - (Number(b.rung) || 0) || (Number(a.page_no) || 0) - (Number(b.page_no) || 0));
  const tracked = []; const seen = new Set();
  for (const k of s.keywords) if (!seen.has(k)) { seen.add(k); tracked.push({ keyword: k, source: 'site', rung: 0, ladder_id: '', head_keyword: '' }); }
  for (const l of lrows) { const k = String(l.keyword).toLowerCase().trim(); if (!seen.has(k)) { seen.add(k); tracked.push({ keyword: k, source: 'ladder', rung: Number(l.rung) || 0, ladder_id: l.ladder_id, head_keyword: String(l.head_keyword || '').toLowerCase() }); } }
  const pages = []; const seenU = new Set();
  for (const l of lrows) { const u = String(l.target_url || '').trim(); if (u && /^https?:\/\//.test(u) && !seenU.has(u)) { seenU.add(u); pages.push({ url: u, keyword: l.keyword, rung: Number(l.rung) || 0, status: l.status || '', ladder_id: l.ladder_id, page_exists: !!l.page_exists }); } }
  const blogs = logRows.filter(r => normD(r.domain) === s.domain);
  for (const b of blogs) { const k = String(b.keyword).toLowerCase().trim(); if (!seen.has(k)) { seen.add(k); tracked.push({ keyword: k, source: 'blog', rung: 0, ladder_id: b.ladder_id || '', head_keyword: '' }); } }
  for (const b of blogs) { const u = String(b.published_url || '').trim(); if (u && /^https?:\/\//.test(u) && !seenU.has(u)) { seenU.add(u); pages.push({ url: u, keyword: b.keyword, rung: 0, status: 'published', ladder_id: b.ladder_id || '', page_exists: true, published_at: b.published_at || '' }); } }
  const pending_publish = blogs.filter(b => b.status === 'started' && !b.published_url).map(b => ({ keyword: b.keyword, started_at: b.started_at || '', days: Math.round((Date.now() - new Date(b.started_at || now).getTime()) / 864e5) }));
  const cutoff = new Date(Date.now() - 35 * 864e5).toISOString();
  const console_alerts = alertRows.filter(a => normD(a.domain) === s.domain && String(a.received_at) >= cutoff).sort((a, b) => String(b.received_at).localeCompare(String(a.received_at))).slice(0, 10).map(a => ({ kind: a.kind, severity: a.severity, subject: a.subject, summary: a.summary, received_at: a.received_at, source: a.source || 'mail' }));
  const cks = checkinRows.filter(c => c.site_id === s.site_id).sort((a, b) => String(b.month).localeCompare(String(a.month)));
  const last_checkin = cks[0] ? { month: cks[0].month, manual_action: !!cks[0].manual_action, security_issue: !!cks[0].security_issue, not_indexed_total: Number(cks[0].not_indexed_total), csv_kind: cks[0].csv_kind || 'none', coverage: (() => { try { return JSON.parse(cks[0].coverage_json || '{}'); } catch (e) { return {}; } })(), notes: cks[0].notes || '', submitted_at: cks[0].submitted_at || '' } : null;
  const checkin_due = !cks.some(c => c.month === now.slice(0, 7));
  const serp = {};
  for (const h of history) { if (normD(h.domain) !== s.domain) continue; const k = String(h.keyword).toLowerCase(); if (!serp[k] || String(h.checked_at) > String(serp[k].checked_at)) serp[k] = { position: Number(h.position), url: h.url || '', checked_at: h.checked_at }; }
  return { json: { site_id: s.site_id, domain: s.domain, gsc_property_hint: s.gsc_property || '', ga4_property_id: String(s.ga4_property_id || '').replace(/^properties\//, ''), country: s.country || '', location_code: Number(s.location_code) || 0, language_code: s.language_code || 'en',
    email: s.email || '', callback_url: s.callback_url || '', request_id: String(trigger.request_id || s.request_id || ''), source: s.source || 'form', status: s.status || 'active', created_at: s.created_at || now, first_run: !s.last_run_at, virtual: !!s.virtual,
    keywords: s.keywords, tracked: tracked.slice(0, CONFIG.max_tracked_keywords), ladder_pages: pages.slice(0, CONFIG.max_inspections), ladder_heads: [...new Set(lrows.map(l => String(l.head_keyword || '').toLowerCase().trim()).filter(Boolean))],
    serp_positions: serp, pending_publish, console_alerts, last_checkin, checkin_due, ranges, on_demand, checked_at: now, config: CONFIG } };
});

// Matches each site to a Search Console property the service account can read: "sc-domain:" (domain property) first,
// then a URL-prefix property for the host (https preferred), or the property named at registration.
const plan = $('Site Plan').all().map(i => i.json).filter(p => p && !p.nothing_to_do);
const res = ($input.first() || {}).json || {};
const gErr = (r) => { if (!r) return 'no response'; const e = r.error; if (!e) return null; if (typeof e === 'string') return e.slice(0, 200); const ctx = (e.context && e.context.data) || {}; const inner = (ctx.error && typeof ctx.error === 'object') ? ctx.error : null; return String((inner && inner.message) || (ctx.error_description ? String(ctx.error || 'error') + ': ' + ctx.error_description : '') || e.message || e.description || e.status || JSON.stringify(e)).slice(0, 200); };   // Google errors: the useful text sits in context.data (invalid_grant: account not found) or in error.message (PERMISSION_DENIED)
const err = res.error ? gErr(res) : (Array.isArray(res.siteEntry) ? null : 'no answer from the Search Console API (credential missing or no access)');
const entries = Array.isArray(res.siteEntry) ? res.siteEntry : [];
const hostOf = (u) => { const m = String(u || '').trim().match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };   // no URL constructor in the n8n Code sandbox (live finding 2026-10-02)
return plan.map(p => {
  const d = p.domain;
  const ok = entries.filter(e => e.siteUrl && e.permissionLevel !== 'siteUnverifiedUser');
  const hinted = p.gsc_property_hint ? ok.find(e => e.siteUrl === p.gsc_property_hint) : null;
  const dom = ok.find(e => e.siteUrl === 'sc-domain:' + d);
  const pref = ok.filter(e => /^https?:\/\//.test(e.siteUrl) && (hostOf(e.siteUrl) === d || hostOf(e.siteUrl).endsWith('.' + d))).sort((a, b) => (a.siteUrl.startsWith('https') ? 0 : 1) - (b.siteUrl.startsWith('https') ? 0 : 1))[0];
  const pick = hinted || dom || pref || null;
  return { json: { ...p, gsc_property: pick ? pick.siteUrl : '', gsc_connected: !!pick, gsc_permission: pick ? pick.permissionLevel : '',
    gsc_error: pick ? null : (err || ('the service account has no access to a Search Console property for ' + d + (entries.length ? ' (it can see: ' + entries.map(e => e.siteUrl).slice(0, 5).join(', ') + ')' : ' (it sees no property at all)'))) } };
});

// Search Analytics requests per connected site: clicks by day for 56 days, the same 28 days a year ago, top queries (with page) and
// pages for both periods, and every tracked keyword as an exact query (with the ranking page) for both periods. All free (Google quota).
const sites = $('Resolve Properties').all().map(i => i.json);
const API = 'https://www.googleapis.com/webmasters/v3/sites/';
const out = [];
sites.forEach((s, idx) => {
  if (!s.gsc_connected) return;
  const base = API + encodeURIComponent(s.gsc_property) + '/searchAnalytics/query';
  const R = s.ranges; const cfg = s.config || {};
  const req = (kind, body, extra) => out.push({ json: { site_idx: idx, site_id: s.site_id, kind, url: base, body: { type: 'web', dataState: 'final', ...body }, ...(extra || {}) } });
  req('by_date', { startDate: R.previous.start, endDate: R.current.end, dimensions: ['date'], rowLimit: 100 });
  req('yoy', { startDate: R.yoy.start, endDate: R.yoy.end, rowLimit: 1 });
  req('queries_cur', { startDate: R.current.start, endDate: R.current.end, dimensions: ['query', 'page'], rowLimit: 500 });
  req('queries_prev', { startDate: R.previous.start, endDate: R.previous.end, dimensions: ['query'], rowLimit: 500 });
  req('pages_cur', { startDate: R.current.start, endDate: R.current.end, dimensions: ['page'], rowLimit: 100 });
  req('pages_prev', { startDate: R.previous.start, endDate: R.previous.end, dimensions: ['page'], rowLimit: 100 });
  (s.tracked || []).slice(0, cfg.max_gsc_keyword_requests || 30).forEach(t => {
    const f = { dimensionFilterGroups: [{ filters: [{ dimension: 'query', operator: 'equals', expression: t.keyword }] }] };
    req('kw_cur', { startDate: R.current.start, endDate: R.current.end, dimensions: ['page'], rowLimit: 5, ...f }, { keyword: t.keyword });
    req('kw_prev', { startDate: R.previous.start, endDate: R.previous.end, dimensions: ['page'], rowLimit: 5, ...f }, { keyword: t.keyword });
  });
});
return out.length ? out : [{ json: { skip: true, reason: 'no site is connected to Search Console' } }];

// Consolidates the Search Analytics responses per site: totals for both periods and a year ago, daily clicks, query movers
// (winners, losers, new, lost), striking-distance queries, CTR gaps, page movers and decaying pages, tracked keyword positions.
const reqs = $('GSC Requests').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const sites = $('Resolve Properties').all().map(i => i.json);
const EXPECTED_CTR = [0.28, 0.15, 0.11, 0.08, 0.07, 0.05, 0.04, 0.035, 0.03, 0.025];   // typical organic CTR by position (industry averages)
const rowsOf = (r) => (r && Array.isArray(r.rows)) ? r.rows.map(x => ({ keys: x.keys || [], clicks: Number(x.clicks) || 0, impressions: Number(x.impressions) || 0, ctr: Number(x.ctr) || 0, position: Number(x.position) || 0 })) : [];
const gErr = (r) => { if (!r) return 'no response'; const e = r.error; if (!e) return null; if (typeof e === 'string') return e.slice(0, 200); const ctx = (e.context && e.context.data) || {}; const inner = (ctx.error && typeof ctx.error === 'object') ? ctx.error : null; return String((inner && inner.message) || (ctx.error_description ? String(ctx.error || 'error') + ': ' + ctx.error_description : '') || e.message || e.description || e.status || JSON.stringify(e)).slice(0, 200); };   // Google errors: the useful text sits in context.data (invalid_grant: account not found) or in error.message (PERMISSION_DENIED)
const errOf = gErr;
const sum = (rows) => { const t = rows.reduce((a, r) => ({ clicks: a.clicks + r.clicks, impressions: a.impressions + r.impressions, pw: a.pw + r.position * r.impressions }), { clicks: 0, impressions: 0, pw: 0 }); return { clicks: t.clicks, impressions: t.impressions, ctr: t.impressions ? +(t.clicks / t.impressions).toFixed(4) : 0, position: t.impressions ? +(t.pw / t.impressions).toFixed(1) : 0 }; };
const pct = (cur, prev) => prev > 0 ? Math.round((cur - prev) / prev * 100) : (cur > 0 ? null : 0);
const acc = new Map();
reqs.forEach((q, i) => {
  if (q.skip) return;
  if (!acc.has(q.site_idx)) acc.set(q.site_idx, { site_idx: q.site_idx, site_id: q.site_id, errors: [], by_date: [], yoy: null, queries_cur: [], queries_prev: [], pages_cur: [], pages_prev: [], kw: {} });
  const a = acc.get(q.site_idx); const r = res[i]; const e = errOf(r);
  if (e) { a.errors.push(q.kind + (q.keyword ? ' "' + q.keyword + '"' : '') + ': ' + e); return; }
  const rows = rowsOf(r);
  if (q.kind === 'kw_cur' || q.kind === 'kw_prev') { const k = a.kw[q.keyword] || (a.kw[q.keyword] = { keyword: q.keyword, cur: null, prev: null }); const top = [...rows].sort((x, y) => y.impressions - x.impressions)[0]; k[q.kind === 'kw_cur' ? 'cur' : 'prev'] = { ...sum(rows), page: top ? top.keys[0] : '' }; }
  else if (q.kind === 'yoy') a.yoy = sum(rows);
  else a[q.kind] = rows;
});
const out = [];
for (const a of acc.values()) {
  const s = sites[a.site_idx] || {}; const R = s.ranges || {}; const cfg = s.config || {};
  const inR = (d, r) => !!r && d >= r.start && d <= r.end;
  const daily = a.by_date.map(r => ({ date: r.keys[0], clicks: r.clicks, impressions: r.impressions, position: +r.position.toFixed(1) })).sort((x, y) => String(x.date).localeCompare(String(y.date)));
  const cur = sum(a.by_date.filter(r => inR(r.keys[0], R.current))), prev = sum(a.by_date.filter(r => inR(r.keys[0], R.previous)));
  // queries: current rows are query x page -> one row per query with its strongest page
  const qmap = new Map();
  for (const r of a.queries_cur) { const q = r.keys[0]; const m = qmap.get(q) || { query: q, rows: [], page: '', pageImp: -1 }; m.rows.push(r); if (r.impressions > m.pageImp) { m.pageImp = r.impressions; m.page = r.keys[1] || ''; } qmap.set(q, m); }
  const prevQ = new Map(a.queries_prev.map(r => [r.keys[0], r]));
  const queries = [...qmap.values()].map(m => { const t = sum(m.rows); const p = prevQ.get(m.query); return { query: m.query, page: m.page, ...t, prev_clicks: p ? p.clicks : 0, prev_impressions: p ? p.impressions : 0, prev_position: p ? +p.position.toFixed(1) : 0, clicks_delta: t.clicks - (p ? p.clicks : 0), position_delta: (p && p.position > 0 && t.position > 0) ? +(p.position - t.position).toFixed(1) : null }; }).sort((x, y) => y.impressions - x.impressions);
  const lost = [...prevQ.values()].filter(p => p.clicks >= 5 && !qmap.has(p.keys[0])).map(p => ({ query: p.keys[0], prev_clicks: p.clicks, prev_position: +p.position.toFixed(1) })).sort((x, y) => y.prev_clicks - x.prev_clicks).slice(0, 10);
  const winners = queries.filter(q => q.clicks_delta >= 5 && q.prev_clicks > 0 && q.clicks_delta / q.prev_clicks >= 0.3).sort((x, y) => y.clicks_delta - x.clicks_delta).slice(0, 10);
  const losers = queries.filter(q => q.clicks_delta <= -5 && q.prev_clicks > 0 && -q.clicks_delta / q.prev_clicks >= 0.3).sort((x, y) => x.clicks_delta - y.clicks_delta).slice(0, 10);
  const brandKey = String(s.domain || '').split('.')[0].toLowerCase().replace(/[^a-z0-9]/g, '');   // 'techand' matches 'techand', 'tech and', 'techand ai' (live finding 2026-10-02)
  const isBrand = (q) => brandKey.length >= 4 && String(q).toLowerCase().replace(/[^a-z0-9]/g, '').includes(brandKey);
  const newQ = queries.filter(q => !prevQ.has(q.query) && q.impressions >= 20 && !isBrand(q.query)).slice(0, 10);
  const striking = queries.filter(q => q.position >= 4 && q.position <= 20 && q.impressions >= (cfg.striking_min_impressions || 30) && !isBrand(q.query)).slice(0, 15);
  const ctrGaps = queries.filter(q => q.position > 0 && q.position <= 10 && q.impressions >= (cfg.ctr_gap_min_impressions || 100) && !isBrand(q.query)).map(q => ({ ...q, expected_ctr: EXPECTED_CTR[Math.max(0, Math.min(9, Math.round(q.position) - 1))] })).filter(q => q.ctr < q.expected_ctr * 0.5).sort((x, y) => (y.impressions * (y.expected_ctr - y.ctr)) - (x.impressions * (x.expected_ctr - x.ctr))).slice(0, 10);
  const prevP = new Map(a.pages_prev.map(r => [r.keys[0], r]));
  const pages = a.pages_cur.map(r => { const p = prevP.get(r.keys[0]); return { page: r.keys[0], clicks: r.clicks, impressions: r.impressions, ctr: r.ctr, position: +r.position.toFixed(1), prev_clicks: p ? p.clicks : 0, prev_impressions: p ? p.impressions : 0, clicks_delta: r.clicks - (p ? p.clicks : 0) }; }).sort((x, y) => y.clicks - x.clicks);
  const decaying = pages.filter(p => p.prev_clicks >= 10 && -p.clicks_delta / p.prev_clicks * 100 >= (cfg.decay_drop_pct || 25)).sort((x, y) => x.clicks_delta - y.clicks_delta).slice(0, 10);
  const rising = pages.filter(p => p.clicks_delta >= 5 && (p.prev_clicks === 0 || p.clicks_delta / p.prev_clicks >= 0.3)).sort((x, y) => y.clicks_delta - x.clicks_delta).slice(0, 10);
  const tracked = Object.values(a.kw).map(k => ({ keyword: k.keyword, position: k.cur && k.cur.impressions ? k.cur.position : 0, prev_position: k.prev && k.prev.impressions ? k.prev.position : 0, clicks: k.cur ? k.cur.clicks : 0, impressions: k.cur ? k.cur.impressions : 0, prev_clicks: k.prev ? k.prev.clicks : 0, prev_impressions: k.prev ? k.prev.impressions : 0, ctr: k.cur ? k.cur.ctr : 0, page: k.cur ? k.cur.page : '' }));
  out.push({ json: { site_idx: a.site_idx, site_id: a.site_id, errors: a.errors, totals: { cur, prev, yoy: a.yoy || null },
    deltas: { clicks_pct: pct(cur.clicks, prev.clicks), impressions_pct: pct(cur.impressions, prev.impressions), position: (prev.position && cur.position) ? +(prev.position - cur.position).toFixed(1) : null, ctr_pts: +((cur.ctr - prev.ctr) * 100).toFixed(2), yoy_clicks_pct: a.yoy ? pct(cur.clicks, a.yoy.clicks) : null },
    daily, query_count: queries.length, queries: queries.slice(0, 100), winners, losers, new_queries: newQ, lost_queries: lost, striking, ctr_gaps: ctrGaps, pages: pages.slice(0, 20), decaying_pages: decaying, rising_pages: rising, tracked } });
}
return out.length ? out : [{ json: { skip: true, reason: 'no Search Console data came back' } }];

// GA4 auto-detection, step 1: one dataStreams request per GA4 property the service account can see, so the property whose
// web stream URL matches the site can be found without the owner looking up the property id. Skipped when every site has an id.
const sites = $('Resolve Properties').all().map(i => i.json);
const need = sites.filter(s => !s.ga4_property_id);
const gErr = (r) => { if (!r) return 'no response'; const e = r.error; if (!e) return null; if (typeof e === 'string') return e.slice(0, 200); const ctx = (e.context && e.context.data) || {}; const inner = (ctx.error && typeof ctx.error === 'object') ? ctx.error : null; return String((inner && inner.message) || (ctx.error_description ? String(ctx.error || 'error') + ': ' + ctx.error_description : '') || e.message || e.description || e.status || JSON.stringify(e)).slice(0, 200); };   // Google errors: the useful text sits in context.data (invalid_grant: account not found) or in error.message (PERMISSION_DENIED)
let acct = {}; try { acct = ($('GA4 Accounts').first() || {}).json || {}; } catch (e) {}
const props = [];
for (const a of (acct.accountSummaries || [])) for (const p of (a.propertySummaries || [])) if (p.property && !props.some(x => x.property === p.property)) props.push({ property: p.property, displayName: p.displayName || '', account: a.displayName || '' });
if (!need.length || !props.length) return [{ json: { skip: true, reason: acct.error ? 'GA4 account list: ' + gErr(acct) : (!need.length ? 'every site has a GA4 property id' : 'the service account sees no GA4 property') } }];
return props.slice(0, 30).map(p => ({ json: { ...p, url: 'https://analyticsadmin.googleapis.com/v1beta/' + p.property + '/dataStreams' } }));

